add('01-introduction','<div class="mast">'+logo()+'<small>AI AD CREATION + UGC + SAAS SOURCE CODE</small></div><div class="eyebrow">BUILD YOUR OWN PLATFORM FOR BRANDS AND AGENCIES</div><h1 class="hero-title">Your own AI ad<br>and <span class="accent">UGC platform.</span></h1><p class="hero-intro">Create product ads and videos with AI presenters. Give customers a huge cast library, voice tools and ready-made stories, all inside your own platform.</p><div class="hero-products">'+product_ad('skincare')+product_ad('headphones')+product_ad('running-shoe')+'</div><div class="big-metrics"><div><strong>25,000+</strong><span>HeyGen presenter looks</span></div><div><strong>1,400+</strong><span>People in the cast library</span></div><div><strong>2,600+</strong><span>HeyGen voices to choose from</span></div></div><div class="pills">'+''.join(badge(t) for t in ['AI product ads','Presenter videos','6 UGC story templates','Voice cloning','Stripe subscriptions','Full source code'])+'</div>'+note('HeyGen account required. Counts verified on 17 October 2026; availability can change. Product visuals are original AI ad concepts.'))
