import re
text_parts=[]
for row in panels:
 source=(P/(row['slug']+'.html')).read_text()
 content=re.sub(r'<[^>]+>',' ',source)
 content=html.unescape(re.sub(r'\s+',' ',content)).strip()
 text_parts.append(row['title']+'\n'+content)
(P/'description-copy.txt').write_text('\n\n'.join(text_parts))
